using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Tilemaps;using UnityEditor;using UnityEditor.SceneManagement;public static class MatchLoggingLayer{public static object Main(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.isDirty||EditorApplication.isPlaying)throw new Exception("Clean edit required");File.Copy(s.path,"output/scene-review/Main.before-pathlayer-disk.unity",true);EditorSceneManager.SaveScene(s,"output/scene-review/Main.before-pathlayer-live.unity",true);var maps=GameObject.Find("Hometown").GetComponentsInChildren<Tilemap>(true);var old=maps.Single(m=>m.name=="-2 Old Path");var path=maps.Single(m=>m.name=="-1 Path");var ids=new Dictionary<int,int>{{14,41},{18,35},{6,5},{4,8},{20,48},{23,47},{1,2},{2,3},{3,5},{15,44},{16,45},{17,40},{34,31},{10,11},{9,32},{0,0}};Undo.RegisterCompleteObjectUndo(path,"Match logging path artwork");int count=0;foreach(var p in old.cellBounds.allPositionsWithin){var world=old.GetCellCenterWorld(p);float x=world.x+75;if(x<11||x>30||world.y> -17||world.y< -28)continue;var t=old.GetTile(p);if(t==null)continue;int id=int.Parse(t.name.Split('_').Last());path.SetTile(path.WorldToCell(world),AssetDatabase.LoadAssetAtPath<TileBase>("Assets/Tilemaps/Tiles/Grass_Tiles_3_Blob_TEST_"+ids[id]+".asset"));count++;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s,"output/scene-review/Main.after-pathlayer-live.unity",true);return count;}}
